mapper.select:
SELECT booth_id, application_id, business_id, name, image_url, intro, category, target_animal, confirmed_at
FROM booth
WHERE booth_id = #{boothId}

mapper.update:
UPDATE booth
name = #{name}, image_url = #{imageUrl}, intro = #{intro}, category = #{category}, target_animal = #{targetAnimal},
WHERE booth_id = #{boothId}

mapper.select:
SELECT booth_item_id, booth_id, name, type, image_url, note
FROM booth_item
WHERE booth_item_id = #{boothItemId}

mapper.update:
UPDATE booth_item
name = #{name}, type = #{type}, image_url = #{imageUrl}, note = #{note},
WHERE booth_item_id = #{boothItemId}

mapper.delete:
DELETE bi FROM booth_item bi
JOIN booth b ON b.booth_id = bi.booth_id
WHERE b.application_id = #{applicationId}

mapper.select:
SELECT EXISTS (
SELECT 1 FROM booth_favorites
WHERE user_id = #{userId} AND booth_id = #{boothId}
)

mapper.delete:
DELETE bf FROM booth_favorites bf
JOIN booth b ON b.booth_id = bf.booth_id
WHERE b.application_id = #{applicationId}
